/* From Uiverse.io by catraco - Tags: button, ring, next, hover effect, startbutton , variables */
.__UIV_SCOPE__ .btn-class-name {
  --color: 180,255, 100;
  border-radius: .5em;
  transition: .3s;
  background-color: rgba(var(--color), .2);
  color: rgb(var(--color));
  fill: rgb(var(--color));
  font-family: monospace;
  font-weight: bolder;
  font-size: x-large;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  cursor: pointer;
  border: 2px solid rgb(var(--color));
  box-shadow: 0 0 10px rgba(var(--color), .4);
  outline: none;
  display: flex;
  align-items: center;
  padding: .5em 1em;
}

.__UIV_SCOPE__ .btn-class-name:hover {
  box-shadow: 0 0 0 5px rgba(var(--color), .5);
}

.__UIV_SCOPE__ .btn-class-name span {
  transform: scale(.8);
  transition: .3s;
}

.__UIV_SCOPE__ .btn-class-name:hover span {
  transform: scale(1);
}

.__UIV_SCOPE__ .btn-class-name svg {
  font-size: 0;
  transform: scale(0.5) translateX(0%) rotate(-180deg);
  transition: .3s;
}

.__UIV_SCOPE__ .btn-class-name:hover svg {
  font-size: 20px;
  transform: scale(1) translateX(20%) rotate(0deg);
}

.__UIV_SCOPE__ .btn-class-name:active {
  transition: 0s;
  box-shadow: 0 0 0 5px rgb(var(--color));
}
